INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'code', 'n./v.', '/kəʊd/', '代码;密码;准则;编码', 'The test uses a code that indicates your overall work personality.', '这个测试用一个代码来表明你整体的职业性格。', 'Launching Your Career', 1, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a personality code', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'council', 'n.', '/ˈkaʊnsl/', '委员会;市政机构;理事会', 'The summer camp council is looking for enthusiastic high school helpers.', '夏令营委员会正在招募热情的高中帮手。', 'Launching Your Career', 2, 0, 'senior', 'wordlist', 'elective4', 'U5', 'the camp council', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'CV', 'n.', '/ˌsiːˈviː/', '履历;简历', 'Please send your CV and a cover letter to the receptionist.', '请把你的简历和求职信发给接待员。', 'Launching Your Career', 3, 0, 'senior', 'wordlist', 'elective4', 'U5', 'send your CV', '美式常用 résumé');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dedicate', 'v.', '/ˈdedɪkeɪt/', '把……奉献给;致力于', 'He dedicated his whole career to research on rare seeds.', '他把整个职业生涯奉献给了对珍稀种子的研究。', 'Launching Your Career', 4, 0, 'senior', 'wordlist', 'elective4', 'U5', 'dedicate to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'detective', 'n.', '/dɪˈtektɪv/', '侦探;警探', 'She has always wanted to become a detective and solve real cases.', '她一直想成为一名侦探,去侦破真实的案件。', 'Launching Your Career', 5, 0, 'senior', 'wordlist', 'elective4', 'U5', 'become a detective', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'employer', 'n.', '/ɪmˈplɔɪə(r)/', '雇主;老板', 'A good CV shows potential employers your skills and experience.', '一份好的简历能向潜在雇主展示你的技能和经验。', 'Launching Your Career', 6, 0, 'senior', 'wordlist', 'elective4', 'U5', 'potential employers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'entrepreneur', 'n.', '/ˌɒntrəprəˈnɜː(r)/', '创业者;企业家', 'He hopes to be an entrepreneur and start his own small company.', '他希望成为一名企业家,创办自己的小公司。', 'Launching Your Career', 7, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a famous entrepreneur', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'estate', 'n.', '/ɪˈsteɪt/', '庄园;房地产;住宅区', 'As an estate agent, she helps people buy and sell houses.', '作为一名房地产经纪人,她帮助人们买卖房屋。', 'Launching Your Career', 8, 0, 'senior', 'wordlist', 'elective4', 'U5', 'an estate agent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'finance', 'n./v.', '/ˈfaɪnæns/', '资金;财政;金融;提供资金', 'She helped manage the finances and receipts during the city tour.', '她在城市游览期间帮助管理财务和收据。', 'Launching Your Career', 9, 0, 'senior', 'wordlist', 'elective4', 'U5', 'manage the finances', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'greedy', 'adj.', '/ˈɡriːdi/', '贪婪的;贪心的', 'It would be greedy to focus only on money and fame in a career.', '在职业中只盯着金钱和名声未免太贪心了。', 'Launching Your Career', 10, 0, 'senior', 'wordlist', 'elective4', 'U5', 'be greedy for', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'handwriting', 'n.', '/ˈhændraɪtɪŋ/', '书写;笔迹;书法', 'The job advertisement asks for a friendly attitude and good handwriting.', '这则招聘广告要求有友好的态度和工整的书写。', 'Launching Your Career', 11, 0, 'senior', 'wordlist', 'elective4', 'U5', 'good handwriting', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'intermediate', 'adj.', '/ˌɪntəˈmiːdiət/', '中级的;中等的;中间的', 'My English is at an intermediate level, so I can talk with visitors.', '我的英语是中级水平,所以我能和访客交谈。', 'Launching Your Career', 12, 0, 'senior', 'wordlist', 'elective4', 'U5', 'an intermediate level', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'justice', 'n.', '/ˈdʒʌstɪs/', '公平;公正;司法', 'I want a career in law because fairness and justice matter to society.', '我想从事法律工作,因为公平和正义对社会很重要。', 'Launching Your Career', 13, 0, 'senior', 'wordlist', 'elective4', 'U5', 'fairness and justice', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'lawyer', 'n.', '/ˈlɔːjə(r)/', '律师', 'He plans to become a lawyer and protect people''s legal rights.', '他打算成为一名律师,保护人们的合法权益。', 'Launching Your Career', 14, 0, 'senior', 'wordlist', 'elective4', 'U5', 'become a lawyer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'orient', 'v.', '/ˈɔːrient/', '使适应;使面对;确定方向', 'Social jobs are people-oriented and often involve helping others.', '社会型工作以人为本,通常包括帮助他人。', 'Launching Your Career', 15, 0, 'senior', 'wordlist', 'elective4', 'U5', 'people-oriented work', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'participant', 'n.', '/pɑːˈtɪsɪpənt/', '参与者;参加者', 'The career test gives each participant a work personality code.', '这个职业测试给每位参与者一个职业性格代码。', 'Launching Your Career', 16, 0, 'senior', 'wordlist', 'elective4', 'U5', 'the participant''s code', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'priority', 'n.', '/praɪˈɒrəti/', '优先事项;首要的事;优先', 'As team captain, I learned how to decide on priorities under pressure.', '作为队长,我学会了在压力下决定优先事项。', 'Launching Your Career', 17, 0, 'senior', 'wordlist', 'elective4', 'U5', 'decide on priorities', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'proficiency', 'n.', '/prəˈfɪʃnsi/', '熟练;精通;娴熟', 'With my proficiency in calligraphy, I could teach short classes.', '凭着我对书法的精通,我可以教授一些短期课程。', 'Launching Your Career', 18, 0, 'senior', 'wordlist', 'elective4', 'U5', 'proficiency in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'profile', 'n./v.', '/ˈprəʊfaɪl/', '简介;概述;侧面;扼要介绍', 'Read the two profiles below and write a paragraph about one person.', '阅读下面两份人物简介,就其中一人写一段话。', 'Launching Your Career', 19, 0, 'senior', 'wordlist', 'elective4', 'U5', 'read the profiles', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'receipt', 'n.', '/rɪˈsiːt/', '收据;收条;收到', 'I kept every receipt while managing the money for the tour.', '在管理这次游览的费用时,我保留了每一张收据。', 'Launching Your Career', 20, 0, 'senior', 'wordlist', 'elective4', 'U5', 'tour receipts', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'receptionist', 'n.', '/rɪˈsepʃənɪst/', '接待员', 'Send your application to the receptionist at the front desk.', '把你的申请发给前台的接待员。', 'Launching Your Career', 21, 0, 'senior', 'wordlist', 'elective4', 'U5', 'send to the receptionist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'scenario', 'n.', '/səˈnɑːriəʊ/', '设想;方案;预测;场景', 'Think about a likely scenario for your future career and plan ahead.', '设想一种你未来职业的可能情景,提前做好规划。', 'Launching Your Career', 22, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a likely scenario', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'supervise', 'v.', '/ˈsuːpəvaɪz/', '主管;指导;监督', 'You will be required to supervise and help out in many tasks.', '你将被要求监督并协助完成许多任务。', 'Launching Your Career', 23, 0, 'senior', 'wordlist', 'elective4', 'U5', 'supervise tasks', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'communist', 'adj./n.', '/ˈkɒmjənɪst/', '共产主义的;共产主义者', 'Marx is known as the founder of international communism.', '马克思被称为国际共产主义的奠基人。', 'Launching Your Career', 24, 0, 'senior', 'wordlist', 'elective4', 'U5', 'international communism', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'socialist', 'adj./n.', '/ˈsəʊʃəlɪst/', '社会主义的;社会主义者', 'He devoted his life''s work to socialist ideas and social justice.', '他把毕生的事业奉献给了社会主义思想和社会公正。', 'Launching Your Career', 25, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a revolutionary socialist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'debt', 'n.', '/det/', '债务;欠款;人情债', 'Some students go into debt to pay for training that helps their career.', '有些学生为支付有助于事业的培训而负债。', 'Launching Your Career', 26, 0, 'senior', 'wordlist', 'elective4', 'U5', 'be in debt', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'graphic', 'adj./n.', '/ˈɡræfɪk/', '绘画的;图案的;图表;图形', 'A graphic designer needs to be creative and imaginative.', '平面设计师需要有创造力和想象力。', 'Launching Your Career', 27, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a graphic designer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'geometry', 'n.', '/dʒiˈɒmətri/', '几何学;几何图形', 'He enjoys numbers, so he wants to teach maths and geometry.', '他喜欢数字,所以想教数学和几何。', 'Launching Your Career', 28, 0, 'senior', 'wordlist', 'elective4', 'U5', 'teach geometry', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'parking', 'n.', '/ˈpɑːkɪŋ/', '停车;停车位', 'One task was to keep the parking area clean for new guests.', '其中一项任务是为新来的客人保持停车区整洁。', 'Launching Your Career', 29, 0, 'senior', 'wordlist', 'elective4', 'U5', 'the parking area', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'disk', 'n.', '/dɪsk/', '磁盘;盘', 'Applications can also be made on paper or disk if you prefer.', '如果你愿意,申请也可以用纸质或磁盘形式提交。', 'Launching Your Career', 30, 0, 'senior', 'wordlist', 'elective4', 'U5', 'on paper or disk', '亦作 disc');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'knit', 'v./n.', '/nɪt/', '编织;针织;(使)紧密结合', 'At the camp, visitors can learn to knit with wool.', '在营地里,游客可以学习用毛线编织。', 'Launching Your Career', 31, 0, 'senior', 'wordlist', 'elective4', 'U5', 'knit with wool', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'wool', 'n.', '/wʊl/', '羊毛;毛线;毛料', 'Knitting with wool is one of the fun activities at the camp.', '用毛线编织是营地里好玩的活动之一。', 'Launching Your Career', 32, 0, 'senior', 'wordlist', 'elective4', 'U5', 'knitting with wool', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sew', 'v.', '/səʊ/', '缝制;缝;做针线活', 'Campers can learn to sew a small purse by hand.', '营员们可以学着手工缝制一个小钱包。', 'Launching Your Career', 33, 0, 'senior', 'wordlist', 'elective4', 'U5', 'sew a purse', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'purse', 'n.', '/pɜːs/', '钱包;手包(尤指女用)', 'Purse sewing is a popular craft activity at our summer camp.', '缝制钱包是我们夏令营里很受欢迎的手工活动。', 'Launching Your Career', 34, 0, 'senior', 'wordlist', 'elective4', 'U5', 'purse sewing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fry', 'v./n.', '/fraɪ/', '油炸;油煎;油炒;油煎食物', 'At the camp, visitors can fry fish over an open fire.', '在营地里,游客可以在篝火上煎鱼。', 'Launching Your Career', 35, 0, 'senior', 'wordlist', 'elective4', 'U5', 'barbecue and fry', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'wrist', 'n.', '/rɪst/', '手腕;腕关节', 'The athlete broke her wrist and needed months of rest.', '这名运动员摔断了手腕,需要数月休养。', 'Launching Your Career', 36, 0, 'senior', 'wordlist', 'elective4', 'U5', 'break a wrist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'collar', 'n.', '/ˈkɒlə(r)/', '衣领;(动物)颈圈', 'At the pet shop, I checked and changed the flea collars.', '在宠物店里,我检查并更换灭蚤颈圈。', 'Launching Your Career', 37, 0, 'senior', 'wordlist', 'elective4', 'U5', 'flea collars', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'drawer', 'n.', '/drɔː(r)/', '抽屉', 'The medicine chest had countless small drawers full of herbs.', '那个药柜有无数装满草药的小抽屉。', 'Launching Your Career', 38, 0, 'senior', 'wordlist', 'elective4', 'U5', 'small drawers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'spy', 'n./v.', '/spaɪ/', '间谍;密探;暗中监视', 'A spy must be observant and good at keeping secrets.', '间谍必须观察敏锐,且善于保守秘密。', 'Launching Your Career', 39, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a police spy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fox', 'n.', '/fɒks/', '狐狸;狡猾的人', 'The Frog and Fox Summer Camp is near a quiet canal.', '蛙与狐夏令营坐落在一条安静的运河旁。', 'Launching Your Career', 40, 0, 'senior', 'wordlist', 'elective4', 'U5', 'the Frog & Fox camp', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'desert', 'n.', '/ˈdezət/', '沙漠;荒漠', 'Dr Zhang dreamed of turning the desert into green farmland.', '张博士梦想把沙漠变成绿色的农田。', 'Launching Your Career', 41, 0, 'senior', 'wordlist', 'elective4', 'U5', 'turn the desert green', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'hydrogen', 'n.', '/ˈhaɪdrədʒən/', '氢;氢气', 'Watching water split into oxygen and hydrogen drew her to chemistry.', '看着水分解成氧气和氢气,使她爱上了化学。', 'Launching Your Career', 42, 0, 'senior', 'wordlist', 'elective4', 'U5', 'oxygen and hydrogen', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'radium', 'n.', '/ˈreɪdiəm/', '镭', 'Marie Curie discovered radium and devoted her life to science.', '玛丽·居里发现了镭,并将一生献给科学。', 'Launching Your Career', 43, 0, 'senior', 'wordlist', 'elective4', 'U5', 'discover radium', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'define', 'v.', '/dɪˈfaɪn/', '给……下定义;界定;阐明', 'First let us define what a great career really means.', '首先让我们界定一下伟大的职业究竟意味着什么。', 'Launching Your Career', 44, 0, 'senior', 'wordlist', 'elective4', 'U5', 'define a great career', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'commit', 'v.', '/kəˈmɪt/', '致力于;承诺;投入', 'To build a great career, you need to commit yourself to something meaningful.', '要成就伟大的事业,你需要把自己投入到有意义的事情上。', 'Launching Your Career', 45, 0, 'senior', 'wordlist', 'elective4', 'U5', 'commit yourself to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'secretary', 'n.', '/ˈsekrətri/', '秘书;书记;部长', 'A secretary should be organised and good with details.', '秘书应当条理清晰,且善于处理细节。', 'Launching Your Career', 46, 0, 'senior', 'wordlist', 'elective4', 'U5', 'work as a secretary', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u5.01', '①不定式作目的状语 / 后置定语 / 主语·宾语·表语', 'A2', 12, '选择性必修四 U5 — want/decide/hope/plan/wish/aim to do 作宾语;the best way / the first person 后置定语用 to do;表目的用 to do;My goal/dream is to do 作表语。', 1, 'elective4', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u5.02', '②不定式作宾语补足语 + 疑问词 + to do', 'A2', 12, '选择性必修四 U5 — ask/advise/encourage/tell/want sb to do(宾补);疑问词 how/what/where/whether + to do 构成不定式短语作宾语等。', 2, 'elective4', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u5.03', '③不定式的时态语态与习语', 'A2', 12, '选择性必修四 U5 — 被动 to be done;完成 to have done;too ... to;enough to;in order to / so as to 表目的。', 3, 'elective4', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'I am writing this letter ____ for the position of camp helper.', 'to apply', 'applying', 'applied', 'apply', 'A', '表目的用不定式 to apply(为了申请)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'She decided ____ a career test before choosing a university major.', 'taking', 'to take', 'taken', 'take', 'B', 'decide to do sth,接不定式作宾语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'My goal is ____ a job that I am truly passionate about.', 'landing', 'landed', 'to land', 'land', 'C', 'be 后接不定式 to land 作表语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'The best way ____ for an interview is to research the company first.', 'preparing', 'prepared', 'prepare', 'to prepare', 'D', 'the way 后用不定式作后置定语(the way to do)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'He hopes ____ his own company after graduating from college.', 'to start', 'starting', 'started', 'start', 'A', 'hope to do sth。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'We are looking for keen young people ____ us at the summer camp.', 'helping', 'to help', 'helped', 'help', 'B', 'people 后用不定式作后置定语,含将来/目的意味。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'Kelly plans ____ a cover letter together with her CV.', 'sending', 'sent', 'to send', 'send', 'C', 'plan to do sth。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), '____ a good career, you first need to know what you are passionate about.', 'Building', 'Built', 'Build', 'To build', 'D', '句首不定式作目的状语(为了建立)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'Her dream is ____ a graphic designer at a famous studio.', 'to become', 'becoming', 'become', 'becomes', 'A', 'be 后接不定式 to become 作表语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'The first thing ____ in your career plan is your long-term goal.', 'writing', 'to write', 'written', 'write', 'B', 'the first thing 后用不定式作后置定语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'I wish ____ exchange students a warm welcome to our country.', 'giving', 'given', 'to give', 'gave', 'C', 'wish to do sth。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'She went to the careers fair ____ more about different jobs.', 'learning', 'learnt', 'learn', 'to learn', 'D', '表目的用不定式 to learn。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), '____ in this field, you must keep developing your skills every year.', 'To succeed', 'Succeeding', 'Succeeded', 'Succeed', 'A', '句首不定式作目的状语(为了成功)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'He aims ____ a lawyer because he cares about fairness and justice.', 'being', 'to be', 'been', 'be', 'B', 'aim to do sth。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'The next step ____ is to tailor your CV to each job you want.', 'taking', 'taken', 'to take', 'take', 'C', 'the step 后用不定式作后置定语(the step to take)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'Many students choose ____ a foreign language to improve their job chances.', 'studying', 'studied', 'study', 'to study', 'D', 'choose to do sth。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'Our plan is ____ a team of enthusiastic helpers for next summer.', 'to build', 'building', 'built', 'build', 'A', 'be 后接不定式 to build 作表语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'She volunteered at a library ____ the children''s section in order.', 'putting', 'to put', 'put', 'puts', 'B', '表目的用不定式 to put(为了整理)。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'The ability ____ priorities is important for any team leader.', 'setting', 'set', 'to set', 'sets', 'C', 'the ability to do sth,不定式作后置定语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.01'), 'He wants ____ his life to research, just as Zhong Yang did.', 'dedicating', 'dedicated', 'dedicate', 'to dedicate', 'D', 'want to do sth。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'The teacher advised us ____ a clear career plan as early as possible.', 'to make', 'making', 'made', 'make', 'A', 'advise sb to do sth,不定式作宾语补足语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'His parents encouraged him ____ a major that suited his interests.', 'choosing', 'to choose', 'chosen', 'choose', 'B', 'encourage sb to do sth。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'I am not sure ____ to write in the opening line of my cover letter.', 'which way', 'how that', 'what', 'where about', 'C', 'what + to do 构成不定式短语(写什么)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'The interviewer asked her ____ about her previous work experience.', 'talking', 'talked', 'talk', 'to talk', 'D', 'ask sb to do sth。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'Could you tell me ____ to apply for this summer camp position?', 'how', 'what that', 'which time', 'how come', 'A', 'how + to do(怎样申请)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'Her mentor told her ____ confident during the whole interview.', 'staying', 'to stay', 'stayed', 'stay', 'B', 'tell sb to do sth。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'I haven''t decided ____ to put first on my list of dream careers.', 'how job', 'what about', 'which job', 'where job', 'C', 'which (job) + to do(把哪份工作放第一)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'The camp council wants every helper ____ guests to the reception area.', 'guiding', 'guided', 'guide', 'to guide', 'D', 'want sb to do sth。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'She showed the new helpers ____ to keep the parking area clean.', 'how', 'what', 'which', 'that', 'A', 'how + to do(怎样保持……整洁)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'My careers teacher expects each of us ____ a short speech about our goals.', 'giving', 'to give', 'given', 'give', 'B', 'expect sb to do sth。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'He didn''t know ____ to send his CV, on paper or by email.', 'what about', 'how come', 'whether', 'which way that', 'C', 'whether + to do(是否……,选哪种方式)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'The employer asked the applicants ____ their best qualities in the letter.', 'describing', 'described', 'describe', 'to describe', 'D', 'ask sb to do sth。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'Please tell me ____ to find reliable information about different careers.', 'where', 'what', 'which', 'that', 'A', 'where + to do(在哪里找到)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'Our coach taught us ____ as a team and decide on priorities together.', 'working', 'to work', 'worked', 'work', 'B', 'teach sb to do sth。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'She still wonders ____ to study at home or at a vocational school.', 'how come', 'what about', 'whether', 'which that', 'C', 'whether + to do(是否……)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'The advisor warned him not ____ only money when choosing a career.', 'chasing', 'chased', 'chase', 'to chase', 'D', 'warn sb (not) to do sth。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'Can you advise me ____ to highlight at the top of my résumé?', 'what', 'how that', 'which way', 'where about', 'A', 'what + to do(突出什么)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'The manager requires every applicant ____ a cover letter with the CV.', 'attaching', 'to attach', 'attached', 'attach', 'B', 'require sb to do sth。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'I''d like someone experienced ____ me how to behave in an interview.', 'telling', 'told', 'to tell', 'tell', 'C', 'would like sb to do sth。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.02'), 'He hasn''t worked out ____ to begin his speech about his future career.', 'what', 'which', 'that', 'how', 'D', 'how + to do(怎样开始)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'Your CV should be tailored to each job ____ a strong impression.', 'to make', 'to be made', 'to making', 'to have made', 'A', '表目的用主动不定式 to make(为了留下印象);主语是 CV 但动作由你完成,主动。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'This kind of attention to detail needs ____ before you send the letter.', 'to pay', 'to be paid', 'paying it', 'to have paid', 'B', '需要被付出 → 被动不定式 to be paid。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'She was too nervous ____ clearly in her very first job interview.', 'speaking', 'spoken', 'to speak', 'to be spoken', 'C', 'too ... to do(太紧张以致说不清)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'He seems ____ a lot about careers before he gave us this advice.', 'to read', 'reading', 'to be read', 'to have read', 'D', '动作先于谓语 → 完成不定式 to have read。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'I am organised enough ____ several tasks at the camp at the same time.', 'to handle', 'handling', 'handled', 'to be handled', 'A', 'adj. + enough + to do(足够……以做……)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'The applicants worked hard ____ a good cover letter and CV.', 'in order writing', 'in order to write', 'in order written', 'in order write', 'B', 'in order to do 表目的。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'Every CV must ____ to match the careers in your plan.', 'adjust', 'be adjusting', 'be adjusted', 'to adjust', 'C', '情态动词 must 后接 be done 被动(简历被调整)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'She studied calligraphy for years ____ teach it to camp visitors one day.', 'so that to', 'so as', 'in order', 'so as to', 'D', 'so as to do 表目的。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'He is glad ____ for the helper position last summer.', 'to have been chosen', 'to choose', 'to be chosen now', 'choosing', 'A', '动作已发生且被动 → 完成被动不定式 to have been chosen。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'The interview questions were not difficult ____ once she relaxed.', 'answering', 'to answer', 'to be answered', 'answered', 'B', '形容词后用主动不定式 to answer(问题易于回答)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'Many skills still need ____ before he is ready for that career.', 'to learn it', 'learning them', 'to be learned', 'to have learned', 'C', '技能需要被学会 → 被动不定式 to be learned。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'The young photographer was patient enough ____ for hours in the grass.', 'waiting', 'waited', 'to be waited', 'to wait', 'D', 'adj. + enough + to do。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'She arrived early ____ avoid being late for the important interview.', 'in order to', 'in order', 'so as', 'for to', 'A', 'in order to do 表目的。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'He was too inexperienced ____ that senior position straight away.', 'getting', 'to get', 'to be got', 'got', 'B', 'too ... to do(太缺经验以致得不到)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'All these documents ought ____ before the application deadline.', 'to submit', 'submitting', 'to be submitted', 'to have submit', 'C', 'ought to + be done 被动(文件被提交)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'She appears ____ a great deal of volunteer work during high school.', 'to do', 'doing', 'to be done', 'to have done', 'D', '动作先于现在 → 完成不定式 to have done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'He spoke slowly ____ that the interviewers could follow him easily.', 'so as to ensure', 'so as ensure', 'in order ensure', 'to ensuring', 'A', 'so as to do 表目的。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'Such a competitive job is hard ____ without solid experience.', 'to be got', 'to get', 'getting', 'got', 'B', '形容词后用主动不定式 to get(此类工作难得到)。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'Your achievements deserve ____ clearly on the first page of the CV.', 'to list', 'listing them', 'to be listed', 'to have listed', 'C', '成就值得被列出 → 被动不定式 to be listed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U5' AND code='e4u5.03'), 'The candidate was confident enough ____ in front of the whole panel.', 'presenting', 'presented', 'to be presented', 'to present', 'D', 'adj. + enough + to do。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'What a Career Aptitude Test Can Do', 'Many high school students have no clear idea about which job would suit them. One useful tool is a career aptitude test. During the test, you answer many questions about what you like and how you behave. Your answers are used to make a code that shows your overall work personality. This code is then used to generate a list of careers that might be right for you. The suggestions are also based on your education and experience, but you can look at higher-level careers as well, which is very useful for students. You could check the basic jobs to see what work you might enjoy now, and then look at more advanced ones so you know what to aim for in the future. However, it is important to remember that the results are only meant for guidance. The real secret to a good career is finding something that you are truly passionate about. So try a test online and start thinking about your future today.', 'Launching Your Career', 166, '[{"q":"How does the test produce a list of career suggestions?","answer":"A","options":["By turning your answers into a personality code first.","By copying jobs from your school report.","By asking your parents what to choose.","By picking jobs at random for everyone."],"explanation":"原文 ''answers are used to make a code… used to generate a list of careers'' 的转述。"},{"q":"Why is looking at higher-level careers useful for students?","answer":"B","options":["It lets them avoid all difficult jobs.","It shows them future goals worth working towards.","It removes the need to study at school.","It guarantees them a high salary."],"explanation":"原文 ''look at more advanced ones so you know what to aim for in the future'' 的转述。"},{"q":"What does the writer say is the real secret to a good career?","answer":"A","options":["Picking a job you genuinely love.","Earning as much money as possible.","Following the test results exactly.","Picking whatever job is easiest."],"explanation":"末段 ''finding something that you are truly passionate about'' 的转述。"}]'::jsonb, '[{"word":"aptitude","cn":"天资;能力倾向"},{"word":"code","cn":"代码"},{"word":"generate","cn":"生成;产生"},{"word":"guidance","cn":"指导;引导"}]'::jsonb, 2, 'elective4', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Choosing a University Major', 'Liu Ming, Susan and Olivia are all thinking hard about which university major to choose. Liu Ming is interested in cybersecurity and data science, because he believes these fields will offer many jobs in the coming years. Susan says she was told that public health is a growing area, and she likes the idea of helping large numbers of people stay well. Olivia hopes to study robotics, but her parents worry that a person''s career might depend too much on which university they get into. The three students also learn that different countries ask for different things. In China, you usually need a good grade and must pass the entrance exam. In the UK, a strong grade is the key. In the USA, students are often asked to write an essay as well. Each of them realises that choosing a major is not only about what they like, but also about what they are good at and what the future may need.', 'Launching Your Career', 162, '[{"q":"Why is Liu Ming interested in cybersecurity and data science?","answer":"B","options":["Because his parents chose them for him.","Because he thinks they will offer many future jobs.","Because they are the easiest majors.","Because his school forced him to."],"explanation":"原文 ''these fields will offer many jobs in the coming years'' 的转述。"},{"q":"What did Susan say she had been told?","answer":"C","options":["That robotics is too difficult.","That she should not go to university.","That the field of public health is expanding.","That all majors are the same."],"explanation":"原文 ''she was told that public health is a growing area'' 的转述。"},{"q":"How is getting into university different in the USA, according to the text?","answer":"D","options":["Students never take any exam.","Only grades from China are accepted.","No good grades are needed at all.","An essay is usually required of applicants there."],"explanation":"原文 ''In the USA, students are often asked to write an essay as well'' 的转述。"}]'::jsonb, '[{"word":"major","cn":"专业"},{"word":"cybersecurity","cn":"网络安全"},{"word":"entrance exam","cn":"入学考试"}]'::jsonb, 2, 'elective4', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Summer Camp Helpers Wanted', 'Are you active and outgoing? Are you passionate about Chinese culture? Would you like to meet young people from other countries? The Frog and Fox Summer Camp is looking for keen high school students to join our team as camp helpers next year. Our camp sits in a beautiful area near a quiet canal, where you will sleep in tents under the stars. You will help us attend to hundreds of students from all over the world, and you may supervise or join in many tasks. These include keeping the parking area clean, guiding new guests to reception, and helping with fun activities such as barbecues, calligraphy and knitting with wool. Successful helpers will ideally have a good level of English, strong teamwork skills, a passion for culture, some experience with animals and a friendly, welcoming attitude. Good handwriting is a plus, too. If this sounds like you, send your CV and a cover letter to our receptionist. We look forward to building a warm and lively team together.', 'Launching Your Career', 169, '[{"q":"Where is the summer camp located?","answer":"A","options":["In a beautiful area beside a quiet canal.","In a busy city centre.","On a small island far from land.","Inside a large shopping mall."],"explanation":"原文 ''a beautiful area near a quiet canal'' 的转述。"},{"q":"Which of these is one of the helper''s possible tasks?","answer":"B","options":["Driving the camp''s buses.","Guiding new guests to the reception area.","Cooking all the meals alone.","Teaching maths and geometry classes."],"explanation":"原文 ''guiding new guests to reception'' 的转述。"},{"q":"What does the advertisement say a successful helper should ideally have?","answer":"C","options":["A university degree in science.","Several years of paid work experience.","A friendly attitude and good teamwork skills.","The ability to speak five languages."],"explanation":"原文 ''strong teamwork skills… a friendly, welcoming attitude'' 的转述。"}]'::jsonb, '[{"word":"supervise","cn":"监督;协助管理"},{"word":"attend to","cn":"照料;接待"},{"word":"cover letter","cn":"求职信"}]'::jsonb, 2, 'elective4', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Kelly''s Application Letter', 'Dear Sir or Madam, I would like to apply for the position of camp helper, and I believe I would be a valuable addition to your team. My English is at an intermediate level, and I have travelled to several English-speaking countries. I have also helped to organise a three-day city tour for visiting exchange students, where I managed the finances and kept the receipts. I have experience working with animals, since I once volunteered at a local pet shop and changed flea collars there. At a local library, I helped to organise the children''s section. As captain of my school table tennis team for two years, I have learned how to lead others and decide on priorities. With my proficiency in Chinese calligraphy, I could even run short classes for your visitors. The chance to welcome exchange students is very exciting, and I am keen to give them a warm welcome they will always remember. I look forward to hearing from you as soon as possible. Yours faithfully, Kelly Xu.', 'Launching Your Career', 171, '[{"q":"What does Kelly say about her level of English?","answer":"D","options":["It is at a beginner level only.","She cannot speak English at all.","It is her first language.","She has reached a middle, intermediate standard."],"explanation":"原文 ''My English is at an intermediate level'' 的转述。"},{"q":"How did Kelly gain experience with animals?","answer":"A","options":["Through unpaid work she once did at a pet shop.","By keeping pets at a zoo.","By studying biology at university.","By raising sheep on a farm."],"explanation":"原文 ''volunteered at a local pet shop and changed flea collars'' 的转述。"},{"q":"What did being team captain teach Kelly?","answer":"B","options":["How to cook for a large group.","The ability to guide a team and set priorities.","How to design a website.","How to repair a tent."],"explanation":"原文 ''learned how to lead others and decide on priorities'' 的转述。"}]'::jsonb, '[{"word":"intermediate","cn":"中级的"},{"word":"proficiency","cn":"熟练;精通"},{"word":"priority","cn":"优先事项"}]'::jsonb, 2, 'elective4', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Making a Career Plan', 'A good career plan makes you think carefully about your future. It asks you to focus on what you want to do and how you are going to achieve it. A plan should also make you consider which careers interest you most, and what skills and training you will need to succeed in them. Along with the plan, you should prepare a CV, which is essential for showing your future employers your skills and experiences. Of course, the CV should be tailored to match the careers in your plan, so that you are well prepared to take every opportunity that comes your way. To get useful ideas, you can look for websites that focus on career advice, or talk to someone older who can guide you. These are things you should start thinking about right now, because they will help to protect your future. With a clear plan and a strong CV, you will feel far more confident when the right chance finally appears.', 'Launching Your Career', 164, '[{"q":"What does a good career plan ask you to focus on?","answer":"C","options":["Only the salary of each job.","Which friends you will work with.","Your aims and the means of reaching them.","How to avoid all hard work."],"explanation":"原文 ''focus on what you want to do and how you are going to achieve it'' 的转述。"},{"q":"Why is a CV described as essential?","answer":"D","options":["It replaces the need for any plan.","It guarantees you the first job you want.","It saves you from writing a cover letter.","It presents your abilities and background to a boss."],"explanation":"原文 ''essential for showing your future employers your skills and experiences'' 的转述。"},{"q":"Why should a CV be tailored to your plan?","answer":"A","options":["So you are ready to take every opportunity.","So it can be much shorter.","So you can copy it from a friend.","So it never needs changing again."],"explanation":"原文 ''tailored to match the careers… well prepared to take every opportunity'' 的转述。"}]'::jsonb, '[{"word":"tailor","cn":"使适合;量身定做"},{"word":"essential","cn":"必不可少的"},{"word":"opportunity","cn":"机会"}]'::jsonb, 2, 'elective4', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'A Teenager''s Passion for His Work', 'Photography has become an easier hobby today, as technology keeps improving. Yet it still takes a great deal of patience and hard work to become a truly successful photographer. Mateusz is a young man who loves wildlife photography. To take his amazing pictures, he hides quietly in long grass or in a tent so that the birds cannot see him. He waits there for hours, dressed in well-disguised clothing, until the perfect moment arrives. In a single session, he may take hundreds of photographs, hoping that just one will be special. His patience has paid off: a museum once recognised his talent with an award for a young wildlife photographer. People often wonder how someone so young can be so successful. The answer seems to be his deep passion, his enthusiasm and his willingness to keep trying. His story shows that, with real love for your work, you can bring even a teenage hobby to an international audience and turn it into the start of a career.', 'Launching Your Career', 167, '[{"q":"Why does Mateusz hide in long grass or a tent?","answer":"B","options":["Because he is afraid of the sun.","To keep the birds from spotting him.","To keep his camera dry.","Because he is hiding from people."],"explanation":"原文 ''hides quietly in long grass or in a tent so that the birds cannot see him'' 的转述。"},{"q":"How did a museum show that it valued his work?","answer":"C","options":["By buying all his cameras.","By offering him a job as a teacher.","By honouring his talent with a young photographer''s prize.","By printing his photos in a textbook."],"explanation":"原文 ''a museum… recognised his talent with an award'' 的转述。"},{"q":"According to the text, what mainly explains his success?","answer":"D","options":["His expensive equipment.","His good luck in the field.","The help of many assistants.","His deep passion and willingness to keep trying."],"explanation":"原文 ''his deep passion, his enthusiasm and his willingness to keep trying'' 的转述。"}]'::jsonb, '[{"word":"wildlife","cn":"野生动植物"},{"word":"well-disguised","cn":"伪装良好的"},{"word":"enthusiasm","cn":"热情"}]'::jsonb, 2, 'elective4', 'U5');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U5', 'My Dream Career', 'Everyone dreams of having a great career, but first we should (1)____ what a great career really means. When I think about this, many ideas (2)____ in my head, such as money, power or fame. Yet it would be (3)____ to care only about money. Please close your eyes and picture someone truly successful — perhaps an entrepreneur, a leader or a (4)____ who once inspired you. My own choice would be Marie Curie, who discovered (5)____ and gave her life to science. For me she is great not because she was famous, but because she made great (6)____ to humankind. Being a female scientist was rare in her time, but she still (7)____ herself to her work. So I have come to a (8)____: if you want a great career, you must commit yourself to something (9)____. I believe all great careers share this one (10)____.', 147, 2, '[{"q":"1","answer":"A","options":["define","forget","waste","sell"],"explanation":"define 界定;给……下定义。"},{"q":"2","answer":"B","options":["sleep","appear","break","hide"],"explanation":"ideas appear 想法浮现。"},{"q":"3","answer":"C","options":["polite","calm","greedy","shy"],"explanation":"greedy 贪心的。"},{"q":"4","answer":"D","options":["price","machine","garden","teacher"],"explanation":"a teacher 一位老师(同类于 entrepreneur/leader)。"},{"q":"5","answer":"A","options":["radium","noise","weather","traffic"],"explanation":"discovered radium 发现镭。"},{"q":"6","answer":"B","options":["mistakes","contributions","prices","noises"],"explanation":"make contributions 做出贡献。"},{"q":"7","answer":"C","options":["sold","lost","dedicated","dropped"],"explanation":"dedicate oneself to 把自己奉献给。"},{"q":"8","answer":"D","options":["shop","river","city","conclusion"],"explanation":"come to a conclusion 得出结论。"},{"q":"9","answer":"A","options":["meaningful","empty","boring","cheap"],"explanation":"something meaningful 有意义的事。"},{"q":"10","answer":"B","options":["price","secret","noise","ticket"],"explanation":"share this secret 共有这个秘诀。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U5', 'Writing My First CV', 'Last week I sat down to write my very first (1)____ for a part-time job. My teacher told me that a good CV must be short and (2)____, so that busy employers can read it quickly. At the top I wrote my name and how to (3)____ me by phone and email. Then I listed my education and any work (4)____ I had, even the small jobs. I also added the (5)____ I am proud of, such as teamwork and good handwriting. My teacher reminded me to (6)____ the CV to match each job, rather than send the same one everywhere. Before sending it, I checked every line to make sure there were no (7)____. Finally I attached a short cover (8)____ to explain why I wanted the job. When I clicked ''send'', I felt both nervous and (9)____. Writing a CV had taught me to think clearly about my own (10)____.', 152, 2, '[{"q":"1","answer":"C","options":["song","meal","CV","game"],"explanation":"my first CV 我的第一份简历。"},{"q":"2","answer":"D","options":["wet","loud","empty","clear"],"explanation":"short and clear 简短清晰。"},{"q":"3","answer":"A","options":["contact","throw","lose","hide"],"explanation":"how to contact me 如何联系我。"},{"q":"4","answer":"B","options":["weather","experience","noise","traffic"],"explanation":"work experience 工作经验。"},{"q":"5","answer":"C","options":["mistakes","prices","skills","noises"],"explanation":"the skills 技能。"},{"q":"6","answer":"D","options":["sell","lose","drop","tailor"],"explanation":"tailor the CV 量身调整简历。"},{"q":"7","answer":"A","options":["mistakes","songs","gardens","rivers"],"explanation":"no mistakes 没有错误。"},{"q":"8","answer":"B","options":["price","letter","noise","ticket"],"explanation":"a cover letter 一封求职信。"},{"q":"9","answer":"C","options":["wet","cold","proud","late"],"explanation":"nervous and proud 既紧张又自豪。"},{"q":"10","answer":"D","options":["price","weather","noise","strengths"],"explanation":"my own strengths 自己的优势。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U5', 'The Day of My Interview', 'On the morning of my job interview, I woke up early and put on smart (1)____. I had already done a lot of (2)____ about the company, so I knew what they did. To avoid being late, I left home in good (3)____ and arrived twenty minutes early. The (4)____ at the front desk smiled and asked me to wait for a moment. When my turn came, I tried to stay (5)____ and answer every question honestly. The interviewer asked me to (6)____ my best qualities and my past experience. I told her about being a team (7)____ and learning to decide on priorities. She seemed pleased and even (8)____ me to apply for a higher position next year. As I left, I felt that all my (9)____ had been worth it. That day taught me that good preparation can turn a scary moment into a real (10)____.', 148, 2, '[{"q":"1","answer":"A","options":["clothes","songs","prices","noises"],"explanation":"smart clothes 得体的衣服。"},{"q":"2","answer":"B","options":["sleep","research","noise","traffic"],"explanation":"do research 做调查。"},{"q":"3","answer":"C","options":["price","weather","time","noise"],"explanation":"in good time 提早;留有余地。"},{"q":"4","answer":"D","options":["river","garden","machine","receptionist"],"explanation":"the receptionist 接待员。"},{"q":"5","answer":"A","options":["calm","wet","cold","late"],"explanation":"stay calm 保持冷静。"},{"q":"6","answer":"B","options":["throw","describe","lose","hide"],"explanation":"describe my qualities 描述我的品质。"},{"q":"7","answer":"C","options":["price","noise","captain","ticket"],"explanation":"a team captain 队长。"},{"q":"8","answer":"D","options":["sold","lost","broke","encouraged"],"explanation":"encouraged me to apply 鼓励我申请。"},{"q":"9","answer":"A","options":["effort","weather","noise","traffic"],"explanation":"all my effort 我的努力。"},{"q":"10","answer":"B","options":["price","chance","noise","garden"],"explanation":"a real chance 真正的机会。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U5', 'Skills That Every Job Needs', 'No matter which career you choose, some skills are always (1)____. The first is teamwork, because most jobs require you to (2)____ well with other people. The second is the ability to (3)____ on priorities, so that you finish the most important task first. Good communication is also (4)____: you must be able to explain your ideas clearly. Many employers say they (5)____ workers who are honest and reliable. It also helps to keep learning, since the world of work keeps (6)____. If you make a mistake, do not be afraid to (7)____ for help. A friendly, welcoming (8)____ can make a real difference in any team. Finally, you should be willing to take (9)____ for your own actions. When you build up these skills, you will be far better (10)____ for whatever career lies ahead of you.', 138, 2, '[{"q":"1","answer":"C","options":["empty","wet","useful","cheap"],"explanation":"always useful 总是有用的。"},{"q":"2","answer":"D","options":["sleep","sell","throw","work"],"explanation":"work well with others 与他人合作。"},{"q":"3","answer":"A","options":["decide","lose","hide","drop"],"explanation":"decide on priorities 决定优先事项。"},{"q":"4","answer":"B","options":["boring","important","empty","wet"],"explanation":"also important 也很重要。"},{"q":"5","answer":"C","options":["forget","waste","value","drop"],"explanation":"value honest workers 看重诚实的员工。"},{"q":"6","answer":"D","options":["sleeping","stopping","falling","changing"],"explanation":"keeps changing 不断变化。"},{"q":"7","answer":"A","options":["ask","sell","hide","lose"],"explanation":"ask for help 求助。"},{"q":"8","answer":"B","options":["price","attitude","noise","garden"],"explanation":"a welcoming attitude 友好的态度。"},{"q":"9","answer":"C","options":["noise","weather","responsibility","traffic"],"explanation":"take responsibility 承担责任。"},{"q":"10","answer":"D","options":["sold","lost","broken","prepared"],"explanation":"better prepared 准备得更好。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U5', 'Following Your Passion', 'People often say that the best careers begin with a real (1)____. When you love what you do, hard work no longer feels like a (2)____. Take the young photographer Mateusz as an (3)____. He spends hours waiting quietly in the grass, (4)____ for the perfect moment to take a photo. Most people would lose their (5)____ after such a long wait, but his passion keeps him going. In one session he may take hundreds of (6)____, hoping that just one will be special. His hard work has finally (7)____ off, and a museum once gave him an (8)____ for his talent. People wonder why someone so young can be so (9)____. The answer is simple: he truly loves his work and refuses to give (10)____. His story reminds us that passion can turn a hobby into a career.', 139, 2, '[{"q":"1","answer":"A","options":["passion","price","noise","ticket"],"explanation":"a real passion 真正的热爱。"},{"q":"2","answer":"B","options":["holiday","struggle","garden","river"],"explanation":"feels like a struggle 像一种苦差。"},{"q":"3","answer":"C","options":["error","city","example","machine"],"explanation":"as an example 举例。"},{"q":"4","answer":"D","options":["sleeping","selling","losing","waiting"],"explanation":"waiting for the moment 等待时机。"},{"q":"5","answer":"A","options":["patience","price","weather","noise"],"explanation":"lose their patience 失去耐心。"},{"q":"6","answer":"B","options":["prices","photographs","noises","tickets"],"explanation":"take photographs 拍照片。"},{"q":"7","answer":"C","options":["sold","broke","paid","lost"],"explanation":"pay off 有了回报。"},{"q":"8","answer":"D","options":["error","noise","garden","award"],"explanation":"an award 一个奖项。"},{"q":"9","answer":"A","options":["successful","empty","wet","cold"],"explanation":"so successful 如此成功。"},{"q":"10","answer":"B","options":["in","up","off","out"],"explanation":"give up 放弃。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U5', 'A Scientist''s Career Path', 'Zhong Yang was a botanist who (1)____ his whole life to studying seeds. As a young man, he had to (2)____ between a comfortable job and a much harder dream. He chose the (3)____ road, because he believed his work could one day help the country. For years he travelled to remote and (4)____ areas where no other botanist had ever been. The journeys were dangerous, and the work demanded great (5)____. Yet he never thought about giving (6)____. He often said that a great career is not about money or (7)____, but about doing something useful for others. His students learned an important (8)____ from him: real success comes from passion and hard work. Today, many young scientists are (9)____ by his story. His life shows that a meaningful career can be (10)____ through patience, courage and love for one''s work.', 142, 2, '[{"q":"1","answer":"C","options":["sold","lost","dedicated","dropped"],"explanation":"dedicated his life to 把一生献给。"},{"q":"2","answer":"D","options":["sleep","throw","hide","choose"],"explanation":"choose between 在……之间选择。"},{"q":"3","answer":"A","options":["harder","wet","empty","cheap"],"explanation":"the harder road 更艰难的路。"},{"q":"4","answer":"B","options":["loud","primitive","rich","warm"],"explanation":"remote and primitive areas 偏远原始地区。"},{"q":"5","answer":"C","options":["price","noise","courage","traffic"],"explanation":"great courage 极大的勇气。"},{"q":"6","answer":"D","options":["in","off","out","up"],"explanation":"give up 放弃。"},{"q":"7","answer":"A","options":["fame","water","rain","snow"],"explanation":"money or fame 金钱或名声。"},{"q":"8","answer":"B","options":["price","lesson","noise","garden"],"explanation":"an important lesson 重要的一课。"},{"q":"9","answer":"C","options":["sold","broken","inspired","lost"],"explanation":"inspired by his story 被他的故事激励。"},{"q":"10","answer":"D","options":["sold","thrown","dropped","achieved"],"explanation":"be achieved 被实现。"}]'::jsonb, 6);
