INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Write a Job Application Letter(写一封求职信)', 'A Job Application Letter for a Summer Camp Helper', '假设你叫李华,你看到蛙与狐夏令营(the Frog & Fox Summer Camp)招募高中帮手。请用英语写一封约100词的求职信,内容包括:① 说明你申请的职位;② 介绍你与岗位相关的技能、经验和性格;③ 说明你能为营地带来什么,并表达期待回复。注意:格式得体,用不定式表达目的和愿望(to apply / to help / I am keen to ...)。', 'Suppose you are Li Hua. You have seen that the Frog & Fox Summer Camp is looking for high school helpers. Write an application letter (about 100 words) including: 1) the position you are applying for; 2) your relevant skills, experience and personality; 3) what you can bring to the camp, and your wish to hear back. Use infinitives to express purpose and intention (to apply / to help / I am keen to ...).', '["说明申请的职位(I would like to apply for the position of ...)","技能与经验(My English is at an intermediate level; I have experience in ...)","性格与能为岗位带来什么(I am a team player; I am keen to ...)","礼貌结尾、表达期待(I look forward to hearing from you.)"]'::jsonb, 70, 100, 'Dear Sir or Madam, I would like to apply for the position of camp helper. I believe I would be a valuable addition to your team. My English is at an intermediate level, and I have travelled to several English-speaking countries. I once volunteered at a local pet shop, so I have experience working with animals. As captain of my school table tennis team for two years, I have learned how to lead others and decide on priorities. I am a friendly team player, and I am keen to give your visitors a warm welcome. I look forward to hearing from you soon. Yours faithfully, Li Hua', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I would like to apply for the position of camp helper.","I have experience working with animals, since I once volunteered at a local pet shop.","As captain of my school team, I have learned how to lead others and decide on priorities.","I am keen to give your visitors a warm welcome they will always remember."]'::jsonb, '[{"wrong":"I would like apply for the position.","correct":"I would like to apply for the position.","note":"would like 后接不定式 to do。"},{"wrong":"I have experience to work with animals.","correct":"I have experience working with animals.","note":"experience (in) doing sth,用动名词,不用不定式。"},{"wrong":"I am keen give them a warm welcome.","correct":"I am keen to give them a warm welcome.","note":"be keen to do sth,固定搭配接不定式。"}]'::jsonb, '【求职信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective4', 'U5', '{"title":"不定式(to do)速查","intro":"不定式 to do 既可作目的状语、后置定语,也可作主语、宾语、表语和宾语补足语。判断口诀:看动词搭配和句法位置——该用不定式时,doing / done / 原形都不对;被动意义用 to be done,先于谓语用 to have done。","table":{"headers":["用法","结构 / 例句"],"rows":[["目的状语","(In order/So as) to do:I am writing to apply for the job."],["后置定语","n. + to do:the best way to prepare;the first thing to do"],["主/宾/表语","want/decide/hope to do;My goal is to land a job."],["宾语补足语","ask/advise/encourage sb to do:She advised us to make a plan."],["疑问词+to do","how/what/where/whether + to do:I don''t know how to start."],["被动不定式","to be done:The CV needs to be tailored."],["完成不定式","to have done:He seems to have read a lot about careers."]]},"specialRules":[{"rule":"want/decide/hope/plan/wish/aim/choose 等只接不定式作宾语","mark":"decide to take √ / decide taking ×"},{"rule":"ask/advise/encourage/tell/expect/require sb + to do 作宾补","mark":"advised us to make √ / advised us making ×"},{"rule":"主语承受动作时用被动不定式 to be done","mark":"Skills need to be learned √"},{"rule":"too + adj. + to do(太……以致不能);adj. + enough + to do(足够……能……)","mark":"too nervous to speak;confident enough to present"}],"why":["不定式表示''目的、将来或一次性的动作'',这正是求职、规划职业时最常表达的意思(为了得到工作而准备、决定去做某事);所以这些语境里要用 to do,而不是表''正在/经常''的 doing 或表''被动完成''的 done。"],"gaokaoPoints":["语法填空高频:用所给动词的正确非谓语形式,常考 to do 与 doing / done 的区分(看搭配与逻辑主语)。","主动 vs 被动:to do 还是 to be done,看逻辑主语是动作的执行者还是承受者。","疑问词+to do 作宾语;in order to / so as to 表目的的同义替换。"],"examVsReal":[{"exam":"I am writing to apply for the position.(考试/书面)","real":"I''m writing about the helper job.","note":"考试求职信偏好 to apply 表目的;真实邮件常更口语、直接点题"},{"exam":"The CV needs to be tailored.(考试,被动不定式)","real":"You should tailor your CV.","note":"考试爱考被动不定式;口语里直接用主动句更自然"}]}'::jsonb);
